items=[]
def asset(n,lesson,section,name,title,alt,caption,explain,source,ref,assumptions='ภาพเขียนเสริม ไม่ใช่ผลทดสอบฮาร์ดแวร์',nets=None):
 d=dict(number=n,lesson=SLUGS[lesson-1],section=section,name='visual-'+name,title=title,alt=alt,caption=caption,explanation=explain,source=source,reference=REF[ref],assumptions=assumptions,nets=nets or [],copyright='Original programmatic illustration; no third-party slide/image copied',review='Model/source/code reviewed; hardware NOT TESTED',width=1120)
 items.append(d);return d
class Draw:
 def __init__(self,d):
  self.d=d;self.s=[];self.y=140
  self.text(28,38,'STUDY  /  IOT '+str(d['number']).zfill(2),26,BLUE)
  for i,l in enumerate(d['title'].split('|')):self.text(28,90+i*48,l,38,INK,weight=700)
  self.y=110+len(d['title'].split('|'))*48
 def text(self,x,y,t,size=32,color=INK,anchor='start',weight=400):
  self.s.append(f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}" text-anchor="{anchor}" font-weight="{weight}">{html.escape(str(t))}</text>')
 def line(self,pts,color=LINE,dash=False,arrow=False,width=3):
  p=' '.join(f'{x},{y}' for x,y in pts);self.s.append(f'<polyline points="{p}" fill="none" stroke="{color}" stroke-width="{width}"'+(' stroke-dasharray="8 6"' if dash else '')+(' marker-end="url(#arrow)"' if arrow else '')+'/>')
 def dot(self,x,y,color=BLUE,r=5):self.s.append(f'<circle cx="{x}" cy="{y}" r="{r}" fill="{color}"/>')
 def rect(self,x,y,w,h,fill=SOFT,stroke='#d0dbe2',rx=12):self.s.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>')
 def card(self,lines,y=None,fill=SOFT,color=INK,x=28,w=504):
  y=self.y if y is None else y;h=len(lines)*44+32;self.rect(x,y,w,h,fill)
  for i,l in enumerate(lines):self.text(x+w/2,y+43+i*44,l,32,color,'middle',600 if i==0 else 400)
  self.y=y+h+28;return y,h
 def flow(self,blocks,connect=True):
  for i,block in enumerate(blocks):
   if i and connect:self.line([(280,self.y-23),(280,self.y-4)],BLUE,arrow=True)
   self.card(block)
 def finish(self):
  h=math.ceil(self.y+48);self.text(28,h-24,'ภาพเสริม • ตรวจรุ่นและวงจรจริงก่อนใช้',26,MUTED)
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="1120" height="{h*2}" viewBox="0 0 560 {h}" role="img" aria-labelledby="title desc" lang="th"><title id="title">{html.escape(self.d["title"].replace("|"," "))}</title><desc id="desc">{html.escape(self.d["alt"])}</desc><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto-start-reverse"><path d="M0 0L9 4.5L0 9" fill="{LINE}"/></marker></defs><rect width="560" height="{h}" fill="#ffffff"/><g font-family="Leelawadee UI, Noto Sans Thai, sans-serif" stroke-linecap="round" stroke-linejoin="round">'+''.join(self.s)+'</g></svg>\n'
  self.d['height']=h*2;self.d['logicalWidth']=560;self.d['bodyFont']=32
  (OUT/(self.d['name']+'.svg')).write_text(svg,encoding='utf-8',newline='\n')
def cards(d,blocks):a=Draw(d);a.flow(blocks,connect=d["number"] in {2,3,6,9});a.finish()
def ground(a,x,y,label=None):
 a.line([(x,y),(x,y+16)]);a.line([(x-18,y+16),(x+18,y+16)]);a.line([(x-12,y+23),(x+12,y+23)]);a.line([(x-6,y+30),(x+6,y+30)])
 if label:a.text(x+32,y+27,label,28)
def netrows(a,rows):
 for left,right,kind in rows:
  y=a.y;a.rect(28,y,218,100);a.rect(314,y,218,100)
  for i,l in enumerate(left.split('|')):a.text(137,y+39+i*38,l,30,INK,'middle')
  for i,l in enumerate(right.split('|')):a.text(423,y+39+i*38,l,30,INK,'middle')
  rev=kind=='rx';a.line([(314 if rev else 246,y+52),(246 if rev else 314,y+52)],TEAL if rev else BLUE,arrow=True);a.y+=125
def plot(a,label,points,y,color=BLUE):
 a.text(28,y,label,32,INK,weight=600);a.line(points,color,width=4)

